describe('ToolRegistry input validation', () => {
  it('rejects input missing a required property with a ToolResponse naming it and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      rejectionNamesRequiredProperty: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      rejectionNamesRequiredProperty: true,
    });
  });
